{"judgments": [
 {"clause_id": "c001", "issues": [
   {"issue": "The date, the Buyer's name, entity type and address are all left blank, so the instrument does not identify on its face who the Buyer is or when it was made. A court asked to enforce it would have to construe extrinsic material to fill those blanks.", "type": 1, "prob": 0.47},
   {"issue": null, "type": 2, "prob": 0.14}
 ]},
 {"clause_id": "c002", "issues": [
   {"issue": "\"Approximately 10.89 acres\" and the reference to Exhibit A leave the exact extent of the parcel to the exhibit, and \"parcel!\" is a scanning artifact. The acreage qualifier alone is a thin basis for dispute.", "type": 1, "prob": 0.17},
   {"issue": "Section 1 conveys the parcel as legally described in Exhibit A, while Section 3 requires a deed containing \"new legal descriptions\" reflecting the City's plat of vacation of Sixth and Abbott Streets and the contiguous properties thereby created. What is sold under Section 1 and what is conveyed under Section 3 may not describe the same land.", "type": 2, "prob": 0.31}
 ]},
 {"clause_id": "c003", "issues": [
   {"issue": null, "type": 1, "prob": 0.16},
   {"issue": null, "type": 2, "prob": 0.18}
 ]},
 {"clause_id": "c004", "issues": [
   {"issue": null, "type": 1, "prob": 0.06},
   {"issue": null, "type": 2, "prob": 0.14}
